package local.station.controller;
import android.app.*;import android.content.*;import android.content.pm.*;import android.os.*;import android.net.Uri;import android.util.Base64;import org.json.*;import java.net.*;import java.io.*;import java.security.*;import java.security.spec.*;import javax.net.ssl.HttpsURLConnection;

/** Public downloads never receive a station token, account or local address. */
final class PublicUpdates {
 static final String CHANNEL="https://github.com/golodgolub-bit/Station-Studio/releases/latest/download/channel.json";
 static final String PUBLIC_KEY="";
 static byte[] fetch(String address,int max)throws Exception{
  for(int redirects=0;redirects<6;redirects++){
   URL url=new URL(address);String h=url.getHost();if(!url.getProtocol().equals("https")||!(h.equals("github.com")||h.equals("release-assets.githubusercontent.com")||h.endsWith(".githubusercontent.com")))throw new IOException("Неподдерживаемый адрес обновления");
   HttpsURLConnection c=(HttpsURLConnection)url.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(12000);c.setReadTimeout(30000);c.setRequestProperty("User-Agent","StationStudio-Updater/2.2");
   try{int code=c.getResponseCode();if(code>=300&&code<400){String next=c.getHeaderField("Location");if(next==null)throw new IOException("Нет адреса загрузки");address=new URL(url,next).toString();continue;}if(code!=200)throw new IOException("Канал обновлений ответил "+code);if(c.getContentLength()>max)throw new IOException("Файл обновления слишком большой");try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>max)throw new IOException("Файл обновления слишком большой");}return out.toByteArray();}}finally{c.disconnect();}
  }throw new IOException("Слишком много перенаправлений");
 }
 static JSONObject manifest()throws Exception{
  JSONObject envelope=new JSONObject(new String(fetch(CHANNEL,262144),"UTF-8"));byte[] payload=Base64.decode(envelope.getString("payload"),Base64.DEFAULT),signature=Base64.decode(envelope.getString("signature"),Base64.DEFAULT);PublicKey key=KeyFactory.getInstance("RSA").generatePublic(new X509EncodedKeySpec(Base64.decode(PUBLIC_KEY,Base64.DEFAULT)));java.security.Signature verifier=java.security.Signature.getInstance("SHA256withRSA");verifier.initVerify(key);verifier.update(payload);if(!verifier.verify(signature))throw new IOException("Подпись каталога обновлений не совпала");return new JSONObject(new String(payload,"UTF-8"));
 }
 static File download(Activity activity,JSONObject info)throws Exception{
  PackageInfo own=activity.getPackageManager().getPackageInfo(activity.getPackageName(),PackageManager.GET_SIGNATURES);JSONObject artifact=info.getJSONObject("controller");if(artifact.getInt("minSdk")>Build.VERSION.SDK_INT)throw new IOException("Эта версия требует более нового Android");int version=info.getInt("versionCode");if(version<=own.versionCode)return null;long size=artifact.getLong("size");if(size<1||size>64*1024*1024)throw new IOException("Некорректный размер обновления");byte[] data=fetch(artifact.getString("url"),64*1024*1024);if(data.length!=size||!hex(MessageDigest.getInstance("SHA-256").digest(data)).equals(artifact.getString("sha256")))throw new IOException("Контрольная сумма обновления не совпала");File file=new File(activity.getCacheDir(),"studio-update.apk");try(FileOutputStream out=new FileOutputStream(file)){out.write(data);}PackageInfo next=activity.getPackageManager().getPackageArchiveInfo(file.getAbsolutePath(),PackageManager.GET_SIGNATURES);if(next==null||!next.packageName.equals(activity.getPackageName())||next.versionCode!=version||own.signatures==null||next.signatures==null||own.signatures.length!=1||next.signatures.length!=1||!MessageDigest.isEqual(own.signatures[0].toByteArray(),next.signatures[0].toByteArray())){file.delete();throw new IOException("Пакет или подпись приложения не совпали");}return file;
 }
 static String hex(byte[] data){StringBuilder b=new StringBuilder();for(byte v:data)b.append(String.format(java.util.Locale.US,"%02x",v&255));return b.toString();}
 static void install(Activity a){Intent i=new Intent(Intent.ACTION_INSTALL_PACKAGE);i.setData(Uri.parse("content://"+a.getPackageName()+".updates/update.apk"));i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);i.putExtra(Intent.EXTRA_RETURN_RESULT,true);a.startActivityForResult(i,91);}
}
